CREATE TYPE public.app_role AS ENUM ('owner');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX one_owner_only ON public.user_roles(role) WHERE role = 'owner';
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(char_length(display_name)<=100));
GRANT SELECT ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_profiles ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'owner'));
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES(NEW.id, left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER create_profile_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.client_access (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, email text NOT NULL UNIQUE CHECK(char_length(email)<=254), starts_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_access TO authenticated;
GRANT ALL ON public.client_access TO service_role;
ALTER TABLE public.client_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_access ON public.client_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'owner'));
CREATE POLICY owner_insert ON public.client_access FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE POLICY owner_update ON public.client_access FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE POLICY owner_delete ON public.client_access FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'owner'));
CREATE FUNCTION public.has_active_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'owner') OR EXISTS(SELECT 1 FROM public.client_access WHERE user_id=auth.uid() AND NOT revoked AND starts_at<=now() AND expires_at>now()) $$;
REVOKE ALL ON FUNCTION public.has_active_access() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_active_access() TO authenticated;
REVOKE ALL ON FUNCTION public.create_user_profile() FROM PUBLIC;